import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import { QRCodeSVG } from 'qrcode.react';

const FileDetailsPage = () => {
  const [fileDetails, setFileDetails] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [copied, setCopied] = useState(false);
  const [activeTab, setActiveTab] = useState('qr'); // 'qr' or 'link'
  const { uuid } = useParams();

  useEffect(() => {
    const fetchFileDetails = async () => {
      try {
        const response = await axios.get(`/api/files/${uuid}`);
        setFileDetails(response.data);
        setLoading(false);
      } catch (error) {
        console.error('Error fetching file details:', error);
        setError('File not found or has been removed');
        setLoading(false);
      }
    };

    fetchFileDetails();
  }, [uuid]);

  const handleCopyLink = () => {
    navigator.clipboard.writeText(fileDetails.downloadLink);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  if (loading) {
    return (
      <div className="file-details-container">
        <div className="loading-spinner">Loading file details...</div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="file-details-container">
        <div className="error-message">{error}</div>
      </div>
    );
  }

  return (
    <div className="file-sharing-page">
      <div className="file-details-container">
        <div className="file-details-card">
          <div className="file-details-header">
            <h2>File Shared Successfully!</h2>
            <p className="file-info">
              <span className="file-name">{fileDetails.filename}</span>
              <span className="file-size">({(fileDetails.size / (1024 * 1024)).toFixed(2)} MB)</span>
            </p>
          </div>

          <div className="share-tabs">
            <div className="tab-headers">
              <button 
                className={`tab-btn ${activeTab === 'qr' ? 'active' : ''}`}
                onClick={() => setActiveTab('qr')}
              >
                QR Code
              </button>
              <button 
                className={`tab-btn ${activeTab === 'link' ? 'active' : ''}`}
                onClick={() => setActiveTab('link')}
              >
                Share Link
              </button>
            </div>

            <div className="tab-content">
              {activeTab === 'qr' && (
                <div className="qr-tab">
                  <div className="qr-container">
                    <QRCodeSVG 
                      value={fileDetails.downloadLink} 
                      size={200}
                      level="H"
                      includeMargin={true}
                      bgColor="#FFFFFF"
                      fgColor="#000000"
                    />
                  </div>
                  <p className="qr-instructions">Scan this QR code to download the file</p>
                </div>
              )}

              {activeTab === 'link' && (
                <div className="link-tab">
                  <div className="link-container">
                    <input 
                      type="text" 
                      value={fileDetails.downloadLink} 
                      readOnly 
                      className="link-input"
                    />
                    <button 
                      className="copy-btn" 
                      onClick={handleCopyLink}
                    >
                      {copied ? 'Copied!' : 'Copy'}
                    </button>
                  </div>
                  <p className="link-instructions">Share this link with anyone to download the file</p>
                </div>
              )}
            </div>
          </div>

          <div className="download-section">
            <a 
              href={`/api/files/download/${uuid}`} 
              className="download-btn"
              download
            >
              Download File
            </a>
          </div>
        </div>
      </div>

      <div className="features-section">
        <h2>Share files directly from your device to anywhere</h2>
        <p className="feature-description">
          Send files of any size directly from your device without ever storing anything online.
        </p>

        <div className="feature-list">
          <div className="feature-item">
            <span className="feature-icon">∞</span>
            <span className="feature-text">No file size limit</span>
          </div>
          <div className="feature-item">
            <span className="feature-icon">⟲</span>
            <span className="feature-text">Peer-to-peer</span>
          </div>
          <div className="feature-item">
            <span className="feature-icon">⚡</span>
            <span className="feature-text">Blazingly fast</span>
          </div>
          <div className="feature-item">
            <span className="feature-icon">🔒</span>
            <span className="feature-text">End-to-end encrypted</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default FileDetailsPage;
